pub fn validate(&self) -> Result<(), Error> {
    if !(1..=20).contains(&self.timeout_secs) {
        return Err("refiner timeout must be 1 to 20 seconds".into());
    }
    match (&self.processor, self.provider.as_deref()) {
        (Some(processor), None) => {
            let path = processor
                .to_str()
                .ok_or("refiner executable path must be UTF-8")?;
            if path.len() > 4096
                || path.chars().any(char::is_control)
                || !processor.is_absolute()
                || !processor.is_file()
            {
                return Err("refiner processor must be an absolute executable file".into());
            }
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                let metadata = std::fs::metadata(processor)
                    .map_err(|_| "refiner executable metadata is unavailable")?;
                if metadata.permissions().mode() & 0o111 == 0 {
                    return Err("refiner processor file is not executable".into());
                }
            }
        }
        (None, Some("native" | "claude" | "codex")) if self.args.is_empty() => {}
        _ => {
            return Err(
                "select exactly one refiner executable or provider native, claude or codex, with arguments only for a custom executable"
                    .into(),
            );
        }

pub(super) fn provider<'a>(requested: &'a str, client: &'a str) -> Result<&'a str, Error> {
    super::client(client)?;
    match requested {
        "native" => Ok(client),
        "claude" | "codex" if requested == client => Ok(client),
        "claude" | "codex" => Err("native provider must match the captured client".into()),
        _ => Err("supported native providers: native, claude, codex".into()),
    }
}

