fn validate_response(input: &Input, response: &Response) -> Result<(), Error> {
    validate_input(input)?;
    if response.schema != 1
        || response.intake_id != input.id
        || response.prompt_digest != input.prompt_digest
    {
        return Err("refiner response does not match this intake and original digest".into());
    }
    match response.action {
        Action::Passthrough => {
            if response.refined_prompt.as_deref() != Some(input.original.as_str())
                || !response.questions.is_empty()
            {
                return Err(
                    "refiner passthrough must preserve exact original bytes and have no questions"
                        .into(),
                );
            }

//! Offline evaluation seam for synthetic refiner inputs, without hook admission.
//!
//! The selected processor still runs with normal process permissions. This path
//! uses the production refiner protocol but never reads or publishes a journal,
//! emits native context, binds an active task or grants workflow authority.

pub(super) fn evaluate(input_path: &Path, config: &RefinerConfig) -> Result<Value, Error> {
    let started = Instant::now();
    let result = (|| {
        let input = read_input(input_path)?;
        config.validate().map_err(|_| "configuration_invalid")?;
        let _cancellation =
            worker::Cancellation::install().map_err(|_| "process_supervision_unavailable")?;
        let response =
            refiner::process(&input, config).map_err(|_| "processing_or_validation_failed")?;
        if worker::interrupted() {
            return Err("interrupted");
        }
        Ok(response)
    })();
    Ok(match result {
        Ok(response) => json!({
            "schema": 1,
            "status": "evaluated",
            "admission": false,
            "response": serde_json::to_value(response)?,
            "elapsed_ms": started.elapsed().as_millis(),
        }),
        Err(reason) => json!({
            "schema": 1,
            "status": "failed",
            "admission": false,
            "reason": reason,
            "elapsed_ms": started.elapsed().as_millis(),
        }),
    })
}

